#!/usr/bin/env python3
import argparse
import base64
import datetime
import os
import re
import sys
import urllib.parse
import urllib.request
import mimetypes
from html.parser import HTMLParser

VERSION = "2.11.0"

BANNER = r""" _____    _____________   __________     ___________________    ___
|     \  /             \ |          |   |                   |  |   |
|      \/       __      \|    __    |   |    ___     ___    |__|   |
|              |  |          |  |   |   |   |   |   |   |          |
|   |\    /|   |__|          |__|   |___|   |   |   |   |    __    |
|   | \__/ |          |\                    |   |   |   |   |  |   |
|___|      |__________| \___________________|   |___|   |___|  |___|
"""

class AssetProcessor:
    def __init__(self, args):
        self.args = args
        self.cache = {}
        self.base_url = args.base_url or "http://localhost/"
        self.cookies = {}
        if args.cookie_file:
            # Simple cookie file parsing (not full Netscape format)
            try:
                with open(args.cookie_file, 'r') as f:
                    for line in f:
                        if not line.startswith('#') and line.strip():
                            parts = line.strip().split('\t')
                            if len(parts) >= 7:
                                self.cookies[parts[5]] = parts[6]
            except Exception:
                pass

    def is_domain_allowed(self, url):
        if not self.args.domain:
            return True
        parsed_url = urllib.parse.urlparse(url)
        domain = parsed_url.netloc
        if not domain:
            return True

        allowed = False
        for d in self.args.domain:
            if domain == d or domain.endswith('.' + d):
                allowed = True
                break

        if self.args.blacklist_domains:
            return not allowed
        else:
            return allowed

    def fetch(self, url, referrer=None):
        if not self.is_domain_allowed(url):
            return None, None

        # Check cache
        if url in self.cache:
            return self.cache[url]

        if not self.args.quiet:
            print(url, file=sys.stderr)

        try:
            if url.startswith('data:'):
                return url, None # Already a data URL

            req = urllib.request.Request(url)
            if self.args.user_agent:
                req.add_header('User-Agent', self.args.user_agent)
            else:
                req.add_header('User-Agent', 'monolith/' + VERSION)

            if referrer:
                req.add_header('Referer', referrer)

            if self.cookies:
                req.add_header('Cookie', '; '.join([f"{k}={v}" for k, v in self.cookies.items()]))

            # Handle insecure TLS
            context = None
            if self.args.insecure:
                import ssl
                context = ssl._create_unverified_context()

            with urllib.request.urlopen(req, timeout=self.args.timeout, context=context) as response:
                content = response.read()
                mime_type = response.info().get_content_type()
                return content, mime_type
        except Exception as e:
            if not self.args.quiet:
                print(f"{url} ({e})", file=sys.stderr)
            if self.args.ignore_errors:
                return b"", "text/plain"
            return None, None

    def to_data_url(self, content, mime_type):
        if content is None:
            return ""
        if isinstance(content, str) and content.startswith('data:'):
            return content
        b64_content = base64.b64encode(content).decode('ascii')
        return f"data:{mime_type};base64,{b64_content}"

    def process_css(self, css_content, base_url):
        if not css_content:
            return ""

        if isinstance(css_content, bytes):
            css_content = css_content.decode('utf-8', errors='replace')

        # Handle @import
        def replace_import(match):
            import_url = match.group(2) or match.group(3)
            full_url = urllib.parse.urljoin(base_url, import_url)
            if self.args.no_css:
                return ""
            content, mime = self.fetch(full_url, referrer=base_url)
            if content:
                processed_content = self.process_css(content, full_url)
                data_url = self.to_data_url(processed_content.encode('utf-8'), "text/css")
                return f'@import url("{data_url}");'
            return match.group(0)

        css_content = re.sub(r'@import\s+(url\s*\(\s*["\']?(.*?)["\']?\s*\)|["\'](.*?)["\'])\s*;', replace_import, css_content)

        # Handle url()
        def replace_url(match):
            url = match.group(2) or match.group(3) or match.group(4)
            if url.startswith('data:'):
                return match.group(0)
            full_url = urllib.parse.urljoin(base_url, url)

            # Check for font exclusion
            if self.args.no_fonts:
                # This is a bit crude, we check if it's likely a font
                if any(full_url.endswith(ext) for ext in ['.woff', '.woff2', '.ttf', '.otf', '.eot']):
                    return 'url("")'

            content, mime = self.fetch(full_url, referrer=base_url)
            if content:
                data_url = self.to_data_url(content, mime or mimetypes.guess_type(full_url)[0] or "application/octet-stream")
                return f'url("{data_url}")'
            return match.group(0)

        css_content = re.sub(r'url\s*\(\s*(["\'])(.*?)\1\s*\)|url\s*\(\s*([^"\'].*?)\s*\)', replace_url, css_content)

        # Handle no_fonts: remove @font-face rules
        if self.args.no_fonts:
            css_content = re.sub(r'@font-face\s*\{[^}]*\}', '', css_content)

        return css_content

class MonolithParser(HTMLParser):
    def __init__(self, processor, base_url):
        super().__init__()
        self.processor = processor
        self.base_url = base_url
        self.output = ""
        self.head_content = ""
        self.body_content = ""
        self.current_part = "body" # default
        self.in_head = False
        self.in_body = False
        self.has_html = False
        self.has_head = False
        self.has_body = False
        self.title = ""
        self.in_title = False
        self.in_noscript = False
        self.noscript_content = ""
        self.csp_parts = []
        self.encoding = processor.args.encoding or "UTF-8"

        # CSP initialization
        if processor.args.isolate:
            self.csp_parts.append("default-src 'unsafe-eval' 'unsafe-inline' data:;")
        if processor.args.no_js:
            self.csp_parts.append("script-src 'none';")
        if processor.args.no_css:
            self.csp_parts.append("style-src 'none';")
        if processor.args.no_images:
            self.csp_parts.append("img-src data:;")
        if processor.args.no_audio:
            self.csp_parts.append("audio-src 'none';")
        if processor.args.no_video:
            self.csp_parts.append("video-src 'none';")
        if processor.args.no_fonts:
            self.csp_parts.append("font-src 'none';")
        if processor.args.no_frames:
            self.csp_parts.append("frame-src 'none'; child-src 'none';")

    def handle_decl(self, decl):
        self.output += f"<!{decl}>"

    def handle_starttag(self, tag, attrs):
        attr_dict = dict(attrs)

        if tag == 'html':
            self.has_html = True
            self.output += "<html"
            for k, v in attrs:
                self.output += f' {k}="{v}"'
            self.output += ">"
            return
        elif tag == 'head':
            self.has_head = True
            self.in_head = True
            self.current_part = "head"
            self.head_content += "<head>"
            # CSP goes at the beginning of head
            if self.csp_parts:
                csp_content = " ".join(self.csp_parts)
                self.head_content += f'<meta http-equiv="Content-Security-Policy" content="{csp_content}"></meta>'
            return
        elif tag == 'body':
            self.has_body = True
            self.in_body = True
            self.current_part = "body"
            self.body_content += "<body"
            for k, v in attrs:
                self.body_content += f' {k}="{v}"'
            self.body_content += ">"
            return
        elif tag == 'title':
            self.in_title = True
        elif tag == 'noscript':
            self.in_noscript = True
            if self.processor.args.unwrap_noscript:
                self.add_content("<!--noscript-->")
            else:
                self.add_content("<noscript>")
            return

        # Process attributes for URLs
        new_attrs = []
        for k, v in attrs:
            if tag == 'link' and k == 'href' and 'stylesheet' in attr_dict.get('rel', ''):
                if self.processor.args.no_css:
                    v = ""
                else:
                    full_url = urllib.parse.urljoin(self.base_url, v)
                    content, mime = self.processor.fetch(full_url, referrer=self.base_url)
                    if content:
                        processed_css = self.processor.process_css(content, full_url)
                        v = self.processor.to_data_url(processed_css.encode('utf-8'), "text/css")
            elif tag == 'link' and k == 'href' and 'icon' in attr_dict.get('rel', ''):
                full_url = urllib.parse.urljoin(self.base_url, v)
                content, mime = self.processor.fetch(full_url, referrer=self.base_url)
                if content:
                    v = self.processor.to_data_url(content, mime or mimetypes.guess_type(full_url)[0] or "image/x-icon")
            elif tag == 'img' and k == 'src':
                if self.processor.args.no_images:
                    v = "data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82"
                else:
                    full_url = urllib.parse.urljoin(self.base_url, v)
                    content, mime = self.processor.fetch(full_url, referrer=self.base_url)
                    if content:
                        v = self.processor.to_data_url(content, mime or mimetypes.guess_type(full_url)[0] or "image/png")
            elif tag == 'img' and k == 'srcset':
                if self.processor.args.no_images:
                    v = ""
                else:
                    v = self.process_srcset(v)
            elif tag == 'source' and k == 'srcset':
                # Determine if it's image, audio or video source
                parent_tag = "" # We don't have parent tag info easily in HTMLParser
                # Just process it as if it's image/media
                v = self.process_srcset(v)
            elif tag in ['video', 'audio', 'source'] and k == 'src':
                is_video = tag == 'video' or (tag == 'source' and self.processor.args.no_video) # rough guess
                if (tag == 'video' and self.processor.args.no_video) or (tag == 'audio' and self.processor.args.no_audio):
                    v = ""
                else:
                    full_url = urllib.parse.urljoin(self.base_url, v)
                    content, mime = self.processor.fetch(full_url, referrer=self.base_url)
                    if content:
                        v = self.processor.to_data_url(content, mime or mimetypes.guess_type(full_url)[0] or ("video/mp4" if tag == 'video' else "audio/mpeg"))
            elif tag == 'iframe' and k == 'src':
                if self.processor.args.no_frames:
                    v = ""
                else:
                    full_url = urllib.parse.urljoin(self.base_url, v)
                    content, mime = self.processor.fetch(full_url, referrer=self.base_url)
                    if content:
                        # Recursively process iframe content
                        # For simplicity, we just use a new parser
                        # But monolith seems to also do this
                        # ... (could be complex)
                        # Let's just do a basic fetch and process if it's HTML
                        if mime == 'text/html' or v.endswith('.html'):
                            p = AssetProcessor(self.processor.args)
                            parser = MonolithParser(p, full_url)
                            parser.feed(content.decode('utf-8', errors='replace'))
                            processed_html = parser.get_result()
                            v = self.processor.to_data_url(processed_html.encode('utf-8'), "text/html")
                        else:
                            v = self.processor.to_data_url(content, mime or "text/html")
            elif tag == 'script' and k == 'src':
                # monolith replaces script src with inline script
                # We'll handle this in handle_endtag by checking if we have a src to fetch
                self.pending_script_src = urllib.parse.urljoin(self.base_url, v)
                continue # Don't add src attribute
            elif k == 'style':
                v = self.processor.process_css(v, self.base_url)

            new_attrs.append((k, v))

        attr_str = "".join([f' {k}="{v}"' for k, v in new_attrs])
        self.add_content(f"<{tag}{attr_str}>")

    def handle_endtag(self, tag):
        if tag == 'html':
            return
        elif tag == 'head':
            self.in_head = False
            self.current_part = "body"
            return
        elif tag == 'body':
            self.in_body = False
            return
        elif tag == 'title':
            self.in_title = False
        elif tag == 'noscript':
            self.in_noscript = False
            if self.processor.args.unwrap_noscript:
                self.add_content("<!--/noscript-->")
            else:
                self.add_content("</noscript>")
            return
        elif tag == 'script' and hasattr(self, 'pending_script_src'):
            if not self.processor.args.no_js:
                content, mime = self.processor.fetch(self.pending_script_src, referrer=self.base_url)
                if content:
                    self.add_content(content.decode('utf-8', errors='replace'))
            del self.pending_script_src

        self.add_content(f"</{tag}>")

    def handle_data(self, data):
        if self.in_title:
            self.title += data

        if hasattr(self, 'pending_script_src'):
            # If we have a pending script src, we ignore data?
            # monolith seems to put both? Actually usually scripts have either src or content
            pass

        if self.lasttag == 'style' and not self.processor.args.no_css:
            data = self.processor.process_css(data, self.base_url)
        elif self.lasttag == 'script' and self.processor.args.no_js:
            data = ""

        self.add_content(data)

    def handle_comment(self, data):
        self.add_content(f"<!--{data}-->")

    def add_content(self, content):
        if self.current_part == "head":
            self.head_content += content
        else:
            self.body_content += content

    def process_srcset(self, srcset):
        parts = srcset.split(',')
        new_parts = []
        for part in parts:
            part = part.strip()
            if not part: continue
            subparts = part.split()
            if not subparts: return srcset
            url = subparts[0]
            descriptors = subparts[1:]
            full_url = urllib.parse.urljoin(self.base_url, url)
            content, mime = self.processor.fetch(full_url, referrer=self.base_url)
            if content:
                data_url = self.processor.to_data_url(content, mime or mimetypes.guess_type(full_url)[0] or "image/png")
                new_parts.append(f"{data_url} {' '.join(descriptors)}".strip())
            else:
                new_parts.append(part)
        return ", ".join(new_parts)

    def get_result(self):
        # Ensure robots meta tag is in head
        self.head_content += '<meta name="robots" content="none"></meta>'
        if self.processor.args.encoding:
            self.head_content += f'<meta charset="{self.processor.args.encoding}"></meta>'

        res = self.output
        if not self.has_html:
            res += "<html>"
        if not self.has_head:
            res += "<head>"
            if self.csp_parts:
                csp_content = " ".join(self.csp_parts)
                res += f'<meta http-equiv="Content-Security-Policy" content="{csp_content}"></meta>'
            res += self.head_content
            res += "</head>"
        else:
            # We already handled adding robots and charset at end of head_content
            # and CSP at start of head_content
            res += self.head_content + "</head>"

        if not self.has_body:
            res += "<body>"
            res += self.body_content
            res += "</body>"
        else:
            res += self.body_content + "</body>"

        if not self.has_html:
            res += "</html>"
        else:
            res += "</html>"

        return res

def main():
    parser = argparse.ArgumentParser(description="monolith", add_help=False)
    parser.add_argument("target", nargs="?", default="-")
    parser.add_argument("-a", "--no-audio", action="store_true")
    parser.add_argument("-b", "--base-url")
    parser.add_argument("-B", "--blacklist-domains", action="store_true")
    parser.add_argument("-c", "--no-css", action="store_true")
    parser.add_argument("-C", "--cookie-file")
    parser.add_argument("-d", "--domain", action="append")
    parser.add_argument("-e", "--ignore-errors", action="store_true")
    parser.add_argument("-E", "--encoding")
    parser.add_argument("-f", "--no-frames", action="store_true")
    parser.add_argument("-F", "--no-fonts", action="store_true")
    parser.add_argument("-i", "--no-images", action="store_true")
    parser.add_argument("-I", "--isolate", action="store_true")
    parser.add_argument("-j", "--no-js", action="store_true")
    parser.add_argument("-k", "--insecure", action="store_true")
    parser.add_argument("-m", "--mhtml", action="store_true")
    parser.add_argument("-M", "--no-metadata", action="store_true")
    parser.add_argument("-n", "--unwrap-noscript", action="store_true")
    parser.add_argument("-o", "--output", default="-")
    parser.add_argument("-q", "--quiet", action="store_true")
    parser.add_argument("-t", "--timeout", type=int, default=60)
    parser.add_argument("-u", "--user-agent")
    parser.add_argument("-v", "--no-video", action="store_true")
    parser.add_argument("-h", "--help", action="store_true")
    parser.add_argument("-V", "--version", action="store_true")

    args = parser.parse_args()

    if args.version:
        print(f"monolith {VERSION}")
        return

    if args.help or (not args.target and sys.stdin.isatty()):
        print(BANNER)
        print(f"monolith {VERSION}")
        print("\nCLI tool and library for saving web pages as a single HTML file")
        print("\nUsage: executable [OPTIONS] <TARGET>")
        print("\nArguments:")
        print("  <TARGET>  URL or file path, use - for STDIN")
        print("\nOptions:")
        print("  -a, --no-audio                      Remove audio sources")
        print("  -b, --base-url <http://localhost/>  Set custom base URL")
        print("  -B, --blacklist-domains             Treat specified domains as blacklist")
        print("  -c, --no-css                        Remove CSS")
        print("  -C, --cookie-file <cookies.txt>     Specify cookie file")
        print("  -d, --domain <example.com>          Specify domains to use for white/black-listing")
        print("  -e, --ignore-errors                 Ignore network errors")
        print("  -E, --encoding <UTF-8>              Enforce custom charset")
        print("  -f, --no-frames                     Remove frames and iframes")
        print("  -F, --no-fonts                      Remove fonts")
        print("  -i, --no-images                     Remove images")
        print("  -I, --isolate                       Cut off document from the Internet")
        print("  -j, --no-js                         Remove JavaScript")
        print("  -k, --insecure                      Allow invalid X.509 (TLS) certificates")
        print("  -m, --mhtml                         Use MHTML as output format")
        print("  -M, --no-metadata                   Exclude timestamp and source information")
        print("  -n, --unwrap-noscript               Replace NOSCRIPT elements with their contents")
        print("  -o, --output <result.html>          File to write to, use - for STDOUT")
        print("  -q, --quiet                         Suppress verbosity")
        print("  -t, --timeout <60>                  Adjust network request timeout")
        print("  -u, --user-agent <Firefox>          Set custom User-Agent string")
        print("  -v, --no-video                      Remove video sources")
        print("  -h, --help                          Print help")
        print("  -V, --version                       Print version")
        return

    # Handle input
    target = args.target
    if target == "-":
        input_data = sys.stdin.read()
        source_url = "http://localhost/"
        is_local = True
    elif os.path.isfile(target):
        with open(target, 'r', encoding='utf-8', errors='replace') as f:
            input_data = f.read()
        source_url = "file://" + os.path.abspath(target)
        is_local = True
    else:
        # Assume it's a URL
        if not target.startswith(('http://', 'https://', 'file://')):
            target = 'http://' + target
        source_url = target
        is_local = target.startswith('file://')
        try:
            req = urllib.request.Request(source_url)
            if args.user_agent:
                req.add_header('User-Agent', args.user_agent)
            with urllib.request.urlopen(req, timeout=args.timeout) as response:
                input_data = response.read().decode('utf-8', errors='replace')
        except Exception as e:
            print(f"Error fetching target: {e}", file=sys.stderr)
            sys.exit(1)

    if not args.quiet:
        print(source_url, file=sys.stderr)

    base_url = args.base_url or source_url
    processor = AssetProcessor(args)
    parser = MonolithParser(processor, base_url)
    parser.feed(input_data)
    result = parser.get_result()

    # Metadata comment
    if not args.no_metadata:
        timestamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        source_info = "local source" if is_local else f"source at {source_url}"
        comment = f"<!-- Saved from {source_info} at {timestamp} using monolith v{VERSION} -->\n"
        result = comment + result

    # Encoding
    if args.encoding:
        output_data = result.encode(args.encoding, errors='replace')
    else:
        output_data = result.encode('utf-8')

    # MHTML wrapping
    if args.mhtml:
        mhtml_boundary = "----=_NextPart_000_0000"
        mhtml_header = f"MIME-Version: 1.0\n"
        mhtml_header += f'Content-Type: multipart/related; boundary="{mhtml_boundary}"\n\n'
        mhtml_header += f"--{mhtml_boundary}\n"
        mhtml_header += f'Content-Type: text/html; charset="{args.encoding or "utf-8"}"\n'
        mhtml_header += f"Content-Location: {base_url}\n\n"
        mhtml_footer = f"\n--{mhtml_boundary}--\n"
        output_data = mhtml_header.encode('ascii') + output_data + mhtml_footer.encode('ascii')

    # Handle output filename with placeholders
    output_path = args.output
    if output_path != "-":
        if "%title%" in output_path or "%timestamp%" in output_path:
            timestamp_val = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H_%M_%SZ")
            title_val = parser.title or "Untitled"
            output_path = output_path.replace("%title%", title_val).replace("%timestamp%", timestamp_val)

        with open(output_path, 'wb') as f:
            f.write(output_data)
    else:
        sys.stdout.buffer.write(output_data)

if __name__ == "__main__":
    main()
EOF
chmod +x monolith.py
