                        fu = urllib.parse.urljoin(self.bu, v); c, m = self.p.fetch(fu, r=self.bu)
                        if c: v = self.p.to_data(self.p.proc_css(c, fu).encode('utf-8'), "text/css")
                elif t == 'link' and k == 'href' and 'icon' in ad.get('rel', ''):
                    fu = urllib.parse.urljoin(self.bu, v); c, m = self.p.fetch(fu, r=self.bu)
                    if c: v = self.p.to_data(c, m or "image/x-icon")
                elif t == 'img' and k == 'src':
                    if self.p.args.no_images: v = "data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82"
                    else:
                        fu = urllib.parse.urljoin(self.bu, v); c, m = self.p.fetch(fu, r=self.bu)
                        if c: v = self.p.to_data(c, m or "image/png")
                elif t == 'img' and k == 'srcset': v = "" if self.p.args.no_images else self.p_srcset(v)
                elif t == 'source' and k == 'srcset': v = self.p_srcset(v)
                elif t in ['video', 'audio', 'source', 'iframe'] and k == 'src':
                    if (t == 'video' and self.p.args.no_video) or (t == 'audio' and self.p.args.no_audio) or (t == 'iframe' and self.p.args.no_frames): v = ""
                    else:
                        fu = urllib.parse.urljoin(self.bu, v); c, m = self.p.fetch(fu, r=self.bu)
                        if c:
                            if t == 'iframe' and (m == 'text/html' or v.endswith('.html')):
                                ap = AssetProcessor(self.p.args); prs = MonolithParser(ap, fu); prs.feed(c.decode('utf-8', errors='replace'))
                                v = self.p.to_data(prs.get_result().encode('utf-8'), "text/html")
                            else: v = self.p.to_data(c, m or "application/octet-stream")
                elif k == 'style': v = self.p.proc_css(v, self.bu)
