            self.curr.append("<{}{}>".format(t, ''.join([' {}="{}"'.format(k, v) for k, v in na])))
    def handle_endtag(self, t):
        if t == 'html': pass
        elif t == 'head': self.curr = self.body
        elif t in ['body', 'html']: pass
        elif t == 'title': self.i_title = False; self.curr.append("</title>")
        elif t == 'script': self.i_script = False; self.curr.append("</script>")
        elif t == 'style': self.i_style = False; self.curr.append("</style>")
        elif t == 'noscript': self.curr.append("<!--/noscript-->" if self.p.args.unwrap_noscript else "</noscript>")
        else: self.curr.append("</{}>".format(t))
    def handle_data(self, d):
        if self.i_title: self.title += d
        if self.i_style: d = self.p.proc_css(d, self.bu)
        if self.i_script and (self.p.args.no_js or self.p.args.mhtml): d = ""
        self.curr.append(d)
    def handle_comment(self, d): self.curr.append("<!--{}-->".format(d))
    def p_srcset(self, s):
        res = []
        for p in s.split(','):
            sub = p.strip().split()
            if not sub: continue
            fu = urllib.parse.urljoin(self.bu, sub[0]); c, m = self.p.fetch(fu, r=self.bu)
            if c: sub[0] = self.p.to_data(c, m or "image/png")
