    def get_result(self):
        csp = []
        if self.p.args.isolate: csp.append("default-src 'unsafe-eval' 'unsafe-inline' data:;")
        if self.p.args.no_js or self.p.args.mhtml: csp.append("script-src 'none';")
        if self.p.args.no_css: csp.append("style-src 'none';")
        if self.p.args.no_images: csp.append("img-src data:;")
        if self.p.args.no_audio: csp.append("audio-src 'none';")
        if self.p.args.no_video: csp.append("video-src 'none';")
        if self.p.args.no_fonts: csp.append("font-src 'none';")
        if self.p.args.no_frames: csp.append("frame-src 'none'; child-src 'none';")
        h = []
        if csp: h.append('<meta http-equiv="Content-Security-Policy" content="{}"></meta>'.format(" ".join(csp)))
