        if self.p.args.encoding: h.append('<meta charset="{}"></meta>'.format(self.p.args.encoding))
        res = "".join(self.res)
        if not self.h_html: res += "<html>"
        res += "<head>" + "".join(h) + "</head>"
        if not self.h_body: res += "<body>" + "".join(self.body) + "</body>"
        else: res += "".join(self.body) + "</body>"
        return res + "</html>"

def main():
