        src_u = t; is_l = t.startswith('file://')
        try:
            req = urllib.request.Request(src_u)
            if args.user_agent: req.add_header('User-Agent', args.user_agent)
            with urllib.request.urlopen(req, timeout=args.timeout) as resp: input_data = resp.read().decode('utf-8', errors='replace')
        except Exception as e: print("Error: {}".format(e), file=sys.stderr); sys.exit(1)
